/*******************************************************************************
* Instrument: D11_SANS  (ILL D11 - H15@ILL, after Farhi 10/08/2003)
* Faithful reconstruction from a component-level textual specification.
*******************************************************************************/
DEFINE INSTRUMENT D11_SANS(Lambda=4.51, string Config="Borkron_1972", Lc=0, iLc=5, Chamfers=0.0002, Waviness=2.5e-5)

